-- Allowed and denied shopper policy cases use real identities and two retailers.
select no_plan();
select tests.create_shoppers_fixture();
reset role;
select tests.act_as('platform_staff');
select is((select count(*) from public.plan_sessions),0::bigint,'platform_staff plan_sessions read boundary');
select is((select count(*) from public.plan_candidates),0::bigint,'platform_staff plan_candidates read boundary');
select is((select count(*) from public.plan_edits),0::bigint,'platform_staff plan_edits read boundary');
select is((select count(*) from public.lists),0::bigint,'platform_staff lists read boundary');
select is((select count(*) from public.list_items),0::bigint,'platform_staff list_items read boundary');
select is((select count(*) from public.follows),0::bigint,'platform_staff follows read boundary');
select is((select count(*) from public.privacy_requests),0::bigint,'platform_staff privacy_requests read boundary');
reset role;
select tests.act_as('organisation_owner');
select is((select count(*) from public.plan_sessions),0::bigint,'organisation_owner plan_sessions read boundary');
select is((select count(*) from public.plan_candidates),0::bigint,'organisation_owner plan_candidates read boundary');
