select is((select count(*) from public.lists),1::bigint,'organisation_owner lists read boundary');
select is((select count(*) from public.list_items),1::bigint,'organisation_owner list_items read boundary');
select is((select count(*) from public.follows),1::bigint,'organisation_owner follows read boundary');
select is((select count(*) from public.privacy_requests),0::bigint,'organisation_owner privacy_requests read boundary');
select is((select count(*) from public.lists where id = 'a2000000-0000-0000-0000-000000000004'),0::bigint,'organisation_owner cannot see another retailer redeemed list');
select is((select count(*) from public.lists where status = 'open'),0::bigint,'retailer cannot read open lists through table policy');
select is((select count(*) from public.follows where not visible_to_shop),0::bigint,'retailer cannot read hidden consent');
