select tests.act_as('signed_in_shopper');
select lives_ok($$insert into public.follows(shopper_id,organisation_id,consent_text_version) values (auth.uid(),'10000000-0000-0000-0000-000000000002','new')$$,'signed_in_shopper can insert own consent');
select lives_ok($$update public.follows set visible_to_shop = true,marketing_opt_in = true where organisation_id = '10000000-0000-0000-0000-000000000002'$$,'signed_in_shopper can update own consent');
select lives_ok($$insert into public.privacy_requests(shopper_id,kind) values (auth.uid(),'export')$$,'signed_in_shopper can request own export');
select throws_ok($$insert into public.privacy_requests(shopper_id,kind) values (tests.get_supabase_uid('organisation_owner'),'export')$$,'42501',null,'signed_in_shopper cannot request another account export');
select lives_ok($$delete from public.follows where organisation_id = '10000000-0000-0000-0000-000000000002'$$,'signed_in_shopper can delete own follow');
reset role;
select tests.act_as('anonymous_shopper');
select lives_ok($$delete from public.follows where organisation_id = '10000000-0000-0000-0000-000000000001'$$,'anonymous shopper can withdraw own consent');
